<?php

// ==========================================
// 1. CONFIGURACIÓN Y CONEXIÓN PDO
// ==========================================
$host     = '127.0.0.1';
$dbname   = 'tu_base_de_datos';
$username = 'tu_usuario';
$password = 'tu_contraseña';
$charset  = 'utf8mb4';

$dsn = "mysql:host=$host;dbname=$dbname;charset=$charset";

$options = [
    PDO::ATTR_ERRMODE            => PDO::ERRMODE_EXCEPTION, // Lanza excepciones en lugar de errores silenciosos
    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,       // Devuelve arrays asociativos por defecto
    PDO::ATTR_EMULATE_PREPARES   => false,                  // Usa sentencias preparadas reales (seguridad reforzada)
];

try {
    $pdo = new PDO($dsn, $username, $password, $options);
} catch (\PDOException $e) {
    // En producción, registra el error en un log en lugar de mostrarlo al usuario
    throw new \RuntimeException("Error fatal al conectar con la base de datos.", (int)$e->getCode(), $e);
}

// ==========================================
// 2. FUNCIÓN: CONSULTA SEGURA CON PARAMETROS
// ==========================================
/**
 * Ejecuta una consulta SELECT segura y devuelve los resultados como array asociativo.
 */
function obtenerRegistros(PDO $pdo, string $estado): array 
{
    try {
        // Consulta con marcador de posición seguro (:estado)
        $sql = "SELECT id, nombre, email FROM usuarios WHERE estado = :estado";

        $stmt = $pdo->prepare($sql);
        $stmt->execute(['estado' => $estado]);

        // fetchAll() devuelve array de arrays asociativos gracias a PDO::FETCH_ASSOC en la conexión
        return $stmt->fetchAll(); 

    } catch (\PDOException $e) {
        // Envuelve la excepción de PDO para mantener capas de abstracción limpias
        throw new \RuntimeException(
            "Error ejecutando la consulta: " . $e->getMessage(), 
            (int)$e->getCode(), 
            $e // Excepción original como 'previous'
        );
    }
}

